"""Reward numeric equality between the last boxed answer and the GSM8K gold answer.

Wired in through ``reward.custom_reward_function.path/name`` (see run_gsm8k_grpo.sh);
verl calls ``compute_score(data_source=..., solution_str=..., ground_truth=...,
extra_info=...)`` from its reward loop and uses the same function for validation.
"""

from decimal import Decimal, InvalidOperation
import re


_NUMBER_RE = re.compile(
    r"[+-]?(?:(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?"
)


def _last_boxed_content(text):
    """Return the contents of the last complete ``\\boxed{...}``, including nested braces."""
    start = text.rfind("\\boxed")
    if start < 0:
        return None

    opening = start + len("\\boxed")
    while opening < len(text) and text[opening].isspace():
        opening += 1
    if opening == len(text) or text[opening] != "{":
        return None

    depth = 0
    for index in range(opening, len(text)):
        if text[index] == "{":
            depth += 1
        elif text[index] == "}":
            depth -= 1
            if depth == 0:
                return text[opening + 1 : index]
    return None


def _parse_number(text):
    # LaTex commonly writes a thousands separator as ``1\,000``.
    normalized = text.strip().replace("\\,", ",")
    if _NUMBER_RE.fullmatch(normalized) is None:
        return None
    try:
        return Decimal(normalized.replace(",", ""))
    except InvalidOperation:
        return None


def compute_score(data_source, solution_str, ground_truth, extra_info=None, **kwargs):
    if not isinstance(solution_str, str):
        return 0.0

    answer = _last_boxed_content(solution_str)
    if answer is None:
        return 0.0

    predicted_number = _parse_number(answer)
    gold_number = _parse_number(str(ground_truth))
    if predicted_number is None or gold_number is None:
        return 0.0
    return float(predicted_number == gold_number)

